function findDuplicates(array):
    sortedArray = sort(array)     // O(n log n)
    duplicates = []

    for i = 0 to length(sortedArray) - 2:
        if sortedArray[i] == sortedArray[i + 1]:
            duplicates.append(sortedArray[i])

    return duplicates
